\label{rem:Phi-objective}
Although our methodology is formulated directly in terms of the estimating equation $\Psi(\ensuremath{\theta^{\star}})=0$, the operator $\Psi$ is also the gradient of a natural convex population objective. In particular, if we define
\begin{equation}
\label{eq:Phi-theta}
    \Phi(\theta)
    :=
    2\,\mathbb{E}\Bigl[
        \exp\Bigl\{-\mfrac{1}{2}Y\left\langle X,\theta \right\rangle\Bigr\}
    \Bigr],
    \qquad\text{for}\,~\theta\in\Theta_R,
\end{equation}
then $\nabla\Phi(\theta)=\Psi(\theta)$. The function $\Phi$ is the population exponential loss, a classical convex surrogate in binary classification; see, e.g., \citet{FriedmanHastieTibshirani2000logreg,Zhang2004classification,BartlettJordanMcAuliffe2006}. Thus, our stochastic approximation procedure can equivalently be viewed as projected stochastic gradient descent on $\Phi$, where we use the stochastic gradient $\widehat{\Psi}(\theta; Y, M, Z)$ as an unbiased estimator of $\nabla \Phi(\theta)$.

The radius $R$ should be viewed as an a priori upper bound on the size of the regression parameter, rather than as a quantity that must be known exactly. In particular, if $ 
  \ensuremath{ 
    \IfNoValueTF{\ensuremath{\theta^{\star}}}
      {\left\lVert _ \right\rVert}
      {\ensuremath{\theta^{\star}}\lVert _ \ensuremath{\theta^{\star}}\rVert} 
  } 
2\le R'$ and only an upper bound $R\ge R'$ is available, then \crtCref{alg:Proj-SA} may simply be run over $\Theta_R$. The choice of $R$ enters only through the projection set and the choice of the step size; the construction of the stochastic operator $\widehat{\Psi}$ itself does not depend on $R$.

\label{cor:sgd-rate-simplified}
Under the conditions of \crtCref{cor:sgd-rate}, there exists a universal constant $C>0$ such that
\begin{align}
\label{eq:sgd-rate-simplified}
    \mathbb{E}\,\bigr\|\widehat{\theta}^{(n)}-\ensuremath{\theta^{\star}}\bigr\|^2
    \le
    \frac{4\,e^{2R}}{nq\mu^2} \cdot
    \begin{cases}
        \,\displaystyle \exp\left\{C\frac{R}{\sqrt{q} }\log(2-q)\right\}, & \text{if}\,~ R\mu\le\sqrt{q},\\ 
        \,\displaystyle \exp\left\{\frac{C}{\mu}\log\left(1+\frac{1-q}{q} \, R^2\mu^2\right)\right\}, & \text{if}\,~ \sqrt{q}<R\mu\le1,\\ 
        \,\displaystyle \exp\left\{\frac{C}{\mu}\log\frac{1}{q}\right\}, & \text{if}\,~ R\mu>1.
    \end{cases}
\end{align}

\label{thm:minimax-lower-bound}
Suppose we have homogeneous missingness, with $q_1 = \cdots = q_d = q$. There exist universal constants $c_0,c_1,C_0,C_1>0$ such that the following holds. Assume the sample-size condition
\begin{equation}
\label{eq:sample-size-cond-main-thm}
    n \ge
    \frac{C_0}{\mu^2} \cdot \max\Biggl\{
        \frac{\exp(2c_1 R)}{qR^2}\;\!,\;\!

        \exp\biggl(
            C_1 \min\biggl\{
                \frac{R}{\sqrt{q}},\frac{1}{\mu}
            \biggr\}
            \log\biggl(\frac{e}{q}\biggr)
        \biggr)
    \Biggr\}.
\end{equation}
Then, the minimax risk $\mathfrak{R}_n(R,\mu,q)$ over the class $(\mathcal{P}_{\mu},\Theta_R)$, as defined in \crtCref{def:minimax-risk}, satisfies 
\[
    \mathfrak{R}_n(R,\mu,q)
    \ge
    \frac{c_0 \, e^{c_1 R}}{nq\mu^2} \cdot
    \begin{cases}
        \displaystyle
        \exp\left\{ c_1\frac{R}{\sqrt{q}} \log(2-q)\right\},
        & \text{if } R\mu\le\sqrt{q},
        \\ 
        \displaystyle
        \exp\left\{
            \frac{c_1}{\mu} \log\left(1+\frac{1-q}{q}R^2\mu^2\right)
        \right\},
        & \text{if } \sqrt{q}<R\mu\le1,
        \\ 
        \displaystyle
        \exp\left\{\frac{c_1}{\mu} \log\left(\frac{1}{q}\right)\right\},
        & \text{if } R\mu>1.
    \end{cases}
\]

\label{lem:A-hat-properties}
    The empirical operator $\widehat{\Psi}$ in \crtCref{eq:A-hat} satisfies the following:
    \begin{itemize}
        \item[(a)] For every $\theta \in \Theta_R$, $\mathbb{E}\bigl[\widehat{\Psi}(\theta)\bigr] = \Psi(\theta)$.

        \item[(b)] For every $\theta \in \Theta_R$, 
        \[
        \mathbb{E}\bigl[\bigl\| \widehat{\Psi}(\theta)\bigr\|^2\bigr] \leq \exp(R) \cdot V_{\boldsymbol{q},R}.
        \]
    \end{itemize}

\label{prop:baseline-assouad}
There exists a universal constant $c>0$ such that, for every observation probability $q\in(0,1]$, radius $R>0$, and curvature parameter $0<\mu\le\nicefrac{1}{3}$, the minimax risk satisfies
\[
    \mathfrak{R}_n(R,\mu,q)
    \ge
    c\cdot\min\left\{
        R^2,\frac{e^{R/4}}{nq\mu^2}
    \right\}.
\]

First, choose the universal constants $c_1, C_0, C_1$ in the sample-size condition Eq.~\eqref{eq:sample-size-cond-main-thm} to satisfy 
\begin{equation}
\label{eq:sample-size-cond-master}
    n \ge
    \frac{C}{\mu^2} \cdot \max\Biggl[
        \frac{e^{R/8}}{qR^2}\;\!,\;\!
        \exp\biggl(
            C \min\biggl\{
                \frac{R}{\sqrt{q}},\frac{1}{\mu}
            \biggr\}
            \log\biggl(\frac{e}{q}\biggr)
        \biggr)
    \Biggr].
\end{equation}
Since $e^{R/8} \geq 1$, this implies that the lower bound on the sample size $n$ in Proposition~\ref{prop:regime-dependent-lower} is in force.  

Applying Proposition~\ref{prop:baseline-assouad}, we obtain the lower bound
\begin{equation}
\label{eq:baseline-lower-final}
    \mathfrak R_n(R,\mu,q) \ge c\cdot\min\left\{
        R^2,\frac{e^{R/4}}{nq\mu^2} 
    \right\} 
    \ge
    c \frac{e^{R/8}}{nq\mu^2},
\end{equation}
where the final inequality follows as the sample-size condition
in Eq.~\eqref{eq:sample-size-cond-master} implies $e^{R/8}/(nq\mu^2) \leq R^2$.

Continuing, we define the quantity
\[
    \zeta(q,R,\mu)
    :=
    \begin{cases}
        \displaystyle \frac{R}{\sqrt q}\log(2-q),
        & \text{if } R\mu\le\sqrt q,\\ 
        \displaystyle \frac{1}{\mu}\log\left(1+\frac{1-q}{q}R^2\mu^2\right),
        & \text{if } \sqrt q<R\mu\le1,\\ 
        \displaystyle \frac{1}{\mu}\log(1/q),
        & \text{if } R\mu>1,
    \end{cases}
\]
and apply Proposition~\ref{prop:regime-dependent-lower} in conjunction with the numeric inequality $\log(2 - q) \leq 1$ to obtain the lower bound 
\begin{equation}
\label{eq:regime-lower-final}
    \mathfrak R_n(R,\mu,q)
    \ge
    \frac{c}{nq\mu^2}\exp\{c\,\zeta(q,R,\mu)\}.
\end{equation}
Finally, combining \crtCref{eq:baseline-lower-final,eq:regime-lower-final} and using $\max\{a,b\}\ge\sqrt{ab}$, we obtain
\[
    \mathfrak R_n(R,\mu,q)
    \ge
    \frac{c\,e^{R/16}}{nq\mu^2} \exp\left\{\frac{c}{2}\zeta(q,R,\mu)\right\}.
\]
This yields the desired result. \hfill \qed

\label{lem:baseline-assouad-divergence}
Suppose that $0 < \alpha\le \nicefrac{R}{24}$. Then, for every $k\in[p]$ and every $\omega\in\{-1,1\}^p$,
\begin{equation}
\label{eq:baseline-edge-chi2-bound}
    \chi^2\bigl(Q_{\omega^{(k)}},Q_\omega\bigr)
    \le
    \frac{16q\alpha^2}{p}\exp\biggl(-\frac{R}{4}\biggr).
\end{equation}
Consequently,
\begin{equation}
\label{eq:baseline-edge-chi2-n}
    \chi^2\Bigl(Q_{\omega^{(k)}}^{\otimes n},Q_\omega^{\otimes n}\Bigr)
    \le
    \exp\biggl\{
        \frac{16nq\alpha^2}{p}\exp\biggl(-\frac{R}{4}\biggr)
    \biggr\}-1.
\end{equation}

\label{lem:two-point-validity}
Let $m=2r+1\ge5$ and $\lambda>0$. Then the following hold.

\begin{enumerate}[label=(\alph*)]
    \item The function $J(\cdot)$ defined in \crtCref{eq:def-J} satisfies all the properties in \crtCref{eq:required-properties-J}, viz.,
    \begin{equation*}
        J(-t)=-J(t),
        \quad~
        \mathbb{E}_0\bigl[J(T)\bigr]=1,
        \quad\text{and}\quad
        \mathbb{E}_0\bigl[J(T) \,\big|\, T_S\bigr]=1
        \quad
        \forall\,S\subseteq[m]\text{ with }|S|\leq r.
    \end{equation*} 
    Moreover, $J$ satisfies the uniform bound:
    \begin{equation*}
        \|J\|_\infty
        \le
        \left( 2+\frac{1}{\sinh^2(\lambda)} \right)^{m/2}.
    \end{equation*}

    \item Suppose that $\alpha\|J\|_\infty\le\nicefrac{1}{2}$.
    Then, \crtCref{eq:two-point-P1X} defines a valid covariate distribution $P_{1,X}$. Also, $P_0$ and $P_1$ are well-specified logistic regression models with parameters $\theta_0$ and $\theta_1$, respectively. Furthermore, the complete-data likelihood ratio satisfies
    \begin{equation}
    \label{eq:complete-data-likelihood-ratio}
        \frac{\mathrm{d}P_1}{\mathrm{d}P_0}(Y,A,B)
        =
        \exp(\alpha YB)
        \bigl\{\cosh(\alpha) - B\sinh(\alpha) \cdot J(A)\bigr\}.
    \end{equation}

    \item Suppose that $\alpha\|J\|_\infty\le\nicefrac{1}{2}$. Under both $P_0$ and $P_1$, $\|X\|_2=1$ almost surely, and
    \begin{equation}
        \mathbb{E}_0[XX^\top]
        =
        \mathbb{E}_1[XX^\top]
        =
        \frac{1}{2}
        \begin{bmatrix}
            \mfrac{1}{m}
            \left\{(1-\rho^2) I_m + \rho^2 \boldsymbol{1}_m \boldsymbol{1}_m^\top \right\} & 0\\ 
            0 & 1
        \end{bmatrix}
        \succeq
        \frac{\operatorname{sech}^2(\lambda)}{2m} I_{m+1}.
    \end{equation}
\end{enumerate}

\label{lem:two-point-divergence}
Let \(m=2r+1\ge1\) be an odd integer. Suppose that
\[
    \alpha\|J\|_\infty\le\frac{1}{2},
    \qquad\text{and}\qquad
    0<\alpha^2\le q.
\]
Then, there exists a universal constant $C>0$ such that
\begin{equation}
\label{eq:two-point-observed-chi2}
    \chi^2(Q_1,Q_0)
    \le
    Cq\alpha^2\,\mathcal{B}_{m,\lambda,q}.
\end{equation}
Consequently, based on $n$ independent observations,
\begin{equation}
\label{eq:two-point-observed-chi2-n}
    \chi^2\left(Q_1^{\otimes n},Q_0^{\otimes n}\right)
    \le
    \exp\left\{
        Cnq\alpha^2\,\mathcal{B}_{m,\lambda,q}
    \right\}-1.
\end{equation}

\label{lem:large-R-assouad-validity}
Let $m=2r+1\ge5$, $\lambda>0$, and $p\ge1$. Suppose that
\begin{equation}
\label{eq:large-R-assouad-validity-conditions}
    m\lambda
    \le
    \frac{R}{4\sqrt{2}},
    \qquad
    \alpha\|J\|_\infty
    \le
    \frac{1}{2},
    \qquad
    p\alpha^2
    \le
    \frac{3R^2}{32}.
\end{equation}
Then, the following hold.

\begin{enumerate}[label=(\alph*)]
    \item For every $\omega\in\{0,1\}^p$, $P_\omega$ is a well-specified logistic model with parameter $\theta_\omega\in\Theta_R$.

    \medskip
    \item Under all $P_{\omega}$, $\|X\|_2=1$ almost surely, for every $\omega\in\{0,1\}^p$. Moreover,
    \begin{equation}
    \label{eq:large-R-assouad-second-moment-lower}
        \mathbb{E}_\omega[XX^\top]
        =
        \frac{1}{2}
        \begin{bmatrix}
            \mfrac{1}{m}
            \left\{(1-\rho^2)I_m + \rho^2 \boldsymbol{1}_m \boldsymbol{1}_m^\top\right\} & 0 \\ 
            0 & \mfrac{1}{p}I_p
        \end{bmatrix}
        \succeq
        \frac{1}{2}
        \min\left\{
            \frac{\operatorname{sech}^2(\lambda)}{m},
            \frac{1}{p}
        \right\}
        I_{m+p}.
    \end{equation}

    \item Fix any $k\in[p]$ such that $\omega\in\{0,1\}^p$ satisfies $\omega_k=0$. Let $\omega^{(k)}$ be the neighboring vertex of $\omega$ obtained by replacing $\omega_k$ by $1$. Then,
    \begin{equation}
    \label{eq:large-R-assouad-edge-separation}
        \|\theta_{\omega^{(k)}}-\theta_\omega\|_2^2
        =
        8\alpha^2.
    \end{equation}
\end{enumerate}

\label{lem:large-R-assouad-hamming}
Suppose that
\[
    \alpha\|J\|_\infty\le\frac{1}{2},
    \qquad\text{and}\qquad
    0<\alpha^2\le q.
\]
Recall the definition of $\mathcal{B}_{m,\lambda,q}$ in \crtCref{eq:def-Bmlq}. Fix any $k\in[p]$ such that $\omega\in\{0,1\}^p$ satisfies $\omega_k=0$. Let $\omega^{(k)}$ be obtained by replacing $\omega_k$ by $1$. Then, there exists a universal constant $C>0$ such that
\begin{equation}
\label{eq:large-R-assouad-edge-chi2}
    \chi^2\left(
        Q_{\omega^{(k)}},
        Q_\omega
    \right)
    \le
    \frac{Cq\alpha^2}{p}
    \mathcal{B}_{m,\lambda,q}.
\end{equation}
Consequently, based on $n$ independent observations,
\begin{equation}
\label{eq:large-R-assouad-edge-chi2-n}
    \chi^2\left(
        Q_{\omega^{(k)}}^{\otimes n},
        Q_\omega^{\otimes n}
    \right)
    \le
    \exp\left\{
        \frac{Cnq\alpha^2}{p}
        \mathcal{B}_{m,\lambda,q}
    \right\}-1.
\end{equation}

\label{lem:generic-assouad-reduction}
Let $m\ge5$ be odd, let $\lambda>0$, and let $p\ge1$ be an integer satisfying
\begin{equation}
\label{eq:generic-assouad-deterministic-conditions}
    m\lambda\le\frac{R}{4\sqrt{2}},
    \quad\,\text{and}\quad\,
    \mu \le
    \frac{1}{2} \min\left\{\frac{\operatorname{sech}^2(\lambda)}{m},\frac{1}{p}\right\}.
\end{equation}
Suppose further that, for a sufficiently large universal constant $C>0$,
\begin{equation}
\label{eq:generic-assouad-sample-size}
    n
    \ge
    \frac{C}{\mathcal{B}_{m,\lambda,q}}
    \max\left\{
        \frac{p}{q^2},\frac{p}{q}\, \bigl(G_\lambda\bigr)^m, \frac{p^2}{qR^2}
    \right\}.
\end{equation}
Then, there exists a universal constant $c>0$ such that
\begin{equation}
\label{eq:generic-assouad-lower-bound}
    \mathfrak{R}_n(R,\mu,q)
    \ge
    c\,
    \frac{p^2}
    {nq\,\mathcal{B}_{m,\lambda,q}}.
\end{equation}

\label{claim:lower-bound-regimes-II-III}
Suppose that $R\mu>\sqrt{q}$. There exist universal constants $c_0,c_1,C_0,C_1>0$ such that, whenever
\begin{equation}
\label{eq:regimes-II-III-sample-size}
    n \ge
    \frac{C_0}{\mu^2}
    \exp\biggl\{ \frac{C_1}{\mu} \log\biggl(\frac{e}{q}\biggr) \biggr\},
\end{equation}
we have
\begin{equation}
\label{eq:lower-bound-regimes-II-III}
    \mathfrak{R}_n(R,\mu,q)
    \ge
    \frac{c_0}{nq\mu^2}
    \exp\biggl\{
        \frac{c_1}{\mu} \log\biggl( 1+\frac{1-q}{q} \min\{R^2\mu^2,1\} \biggr)
    \biggr\}.
\end{equation}

To begin, fix universal constants $c',c''>0$ such that
\begin{equation}
\label{eq:choice-a-b}
    c'\le\min\left\{\frac{\operatorname{sech}^2(2)}{2},\frac{1}{8\sqrt{2}}\right\} < \frac{1}{25},
    \quad\,\text{and}\quad\,
    c''\le\frac{1}{2}.
\end{equation}

We also fix a sufficiently small universal constant
\begin{equation}
\label{eq:mu-critical}
    \mu_{\mathrm{crit}}\le\min\left\{\frac{c'}{6},\frac{c''}{2}\right\} < \frac{1}{100},
\end{equation}
and write $L_q:=\log(e/q) = 1 + \log(1/q) \ge 1$.

\begin{proof}[Proof of \crtCref{claim:lower-bound-regime-I}]
We prove \crtCref{claim:lower-bound-regime-I} by separating the cases where $R/\sqrt{q}$ is bounded, and where $R/\sqrt{q}$ is unbounded. Set $u:=R/\sqrt{q}$, so that $u\le\mu^{-1}$ in the regime of the claim. Also, choose $U_0\ge\max\bigl\{6/c',2/c'',1\bigr\}$.

\medskip\noindent
\underline{\emph{Case 1: $u\le U_0$}}.
By \crtCref{prop:baseline-assouad} and the fact that $e^{R/4}\ge1$,
\[
    \mathfrak{R}_n(R,\mu,q)\ge c \cdot \min\left\{R^2,\frac{1}{nq\mu^2}\right\}.
\]
Hence, whenever $n\ge C/(q\mu^2R^2)$, we obtain $\mathfrak{R}_n(R,\mu,q)\ge c/(nq\mu^2)$. Since $u\le U_0$, we have
\begin{equation}
\label{eq:regime-I-small-u}
    \mathfrak{R}_n(R,\mu,q)\ge\frac{c}{nq\mu^2}\exp(cu)
    =\frac{c}{nq\mu^2}\exp\left\{c\frac{R}{\sqrt{q}}\right\}.
\end{equation}

\noindent
\underline{\emph{Case 2: $u > U_0$}}.
Set
\begin{equation}
\label{eq:regime-I-parameters}
    \lambda:=2\sqrt{q},
    \quad\,\text{and}\quad\,
    p:=\left\lfloor\frac{c''}{\mu}\right\rfloor.
\end{equation}

Also, let $m$ be the largest positive odd integer satisfying $m\le c'u$. Then, thanks to the choice of $U_0$, we have $m\ge5$, and since consecutive positive odd integers differ by $2$,
\begin{equation}
\label{eq:regime-I-m}
    \frac{2c'u}{3}\le m\le c'u.
\end{equation}
By \crtCref{eq:choice-a-b}, $m\lambda\le2c'R\le R/(4\sqrt{2})$. Moreover, since $u\le\mu^{-1}$ and $\lambda\le2$,
\[
    m\le\frac{c'}{\mu}\le\frac{\operatorname{sech}^2(2)}{2\mu}
    \le\frac{\operatorname{sech}^2(\lambda)}{2\mu}.
\]
Also, $u>U_0\ge2/c''$ and $u\le\mu^{-1}$ imply $c''/\mu>2$. Thus,
\begin{equation}
\label{eq:regime-I-p}
    \frac{c''}{2\mu}\le p\le\frac{c''}{\mu}.
\end{equation}
Since $c''\le1/2$, we also have $p\le (2\mu)^{-1}$. Therefore, the deterministic conditions \eqref{eq:generic-assouad-deterministic-conditions} in \crtCref{lem:generic-assouad-reduction} are satisfied.

We next control $\mathcal{B}_{m,\lambda,q}$ (\crtCref{eq:def-Bmlq}). For the present choice of $\lambda$, let $t := q/\sinh^2(2\sqrt{q})$.
Since $x\mapsto\sinh(x)/x$ is increasing on $(0,\infty)$, $1/\sinh^2(2)\le t\le1/4$. Recalling the function $\beta(\cdot)$ from \crtCref{eq:beta-function}, define
\[
    \underline{\beta}:=\beta\left(\frac{1}{\sinh^2(2)}\right)>0,
    \qquad
    \overline{\beta}:=\beta\left(\frac{1}{4}\right)=\frac{1+\sqrt{17}}{8}<1.
\]

Since $\beta(\cdot)$ is a strictly increasing function on $[0,\infty)$, we have $\underline{\beta}\le\beta(t)\le\overline{\beta}$. Hence, using \crtCref{eq:regime-I-m},
\begin{equation}
\label{eq:regime-I-B-bounds}
    \exp(\underline{c}u)\le\mathcal{B}_{m,\lambda,q}^{-1}\le\exp(\overline{c}u)
\end{equation}
for universal constants $\underline{c},\overline{c}>0$. 

It remains to verify the sample-size condition \eqref{eq:generic-assouad-sample-size} in \crtCref{lem:generic-assouad-reduction}. Since $\sinh(2\sqrt{q})\ge2\sqrt{q}$, we have $G_\lambda\le2+(4q)^{-1}\le C/q$, and therefore $(G_\lambda)^m \le \exp(CuL_q)$. Combining this with \crtCref{eq:regime-I-p,eq:regime-I-B-bounds}, and using $u\ge1$, $R^2=u^2q$, and $\mu\le1$, yields
\begin{equation}
\label{eq:regime-I-sample-size-control}
    \frac{1}{\mathcal{B}_{m,\lambda,q}}
    \max\left\{\frac{p}{q^2},\frac{p}{q}\,\bigl(G_\lambda\bigr)^m,\frac{p^2}{qR^2}\right\}
    \le\frac{C}{\mu^2}\exp(C'uL_q)
\end{equation}
for universal constants $C,C'>0$. Consequently, the sample-size condition \eqref{eq:generic-assouad-sample-size} of \crtCref{lem:generic-assouad-reduction} holds whenever
\begin{equation}
\label{eq:regime-I-large-u-sample-size}
    n\ge\frac{C}{\mu^2}
    \exp\left\{C'\frac{R}{\sqrt{q}}\log\left(\frac{e}{q}\right)\right\}.
\end{equation}

Applying \crtCref{lem:generic-assouad-reduction} and using \crtCref{eq:regime-I-p,eq:regime-I-B-bounds}, we conclude that
\begin{equation}
\label{eq:regime-I-large-u}
    \mathfrak{R}_n(R,\mu,q)
    \ge\frac{c}{nq\mu^2}
    \exp\left\{c\frac{R}{\sqrt{q}}\right\}.
\end{equation}

Combining \crtCref{eq:regime-I-small-u,eq:regime-I-large-u}, we obtain the desired lower bound throughout $R\mu\le\sqrt{q}$: provided
\[
    n\ge\frac{C_0}{q\mu^2R^2},
    \quad\,\text{and}\quad\,
    n\ge\frac{C_1}{\mu^2}
    \exp\left\{C_2\frac{R}{\sqrt{q}}\log\left(\frac{e}{q}\right)\right\},
\]
for sufficiently large universal constants $C_0,C_1,C_2>0$,
\begin{equation}
\label{eq:lower-bound-regime-I}
    \mathfrak{R}_n(R,\mu,q)
    \ge\frac{c}{nq\mu^2}
    \exp\left\{c\frac{R}{\sqrt{q}}\right\}.
\end{equation}
This proves \crtCref{claim:lower-bound-regime-I}.
\end{proof}



\begin{proof}[Proof of \crtCref{claim:lower-bound-regimes-II-III}]
Set $h:=\min\{R\mu,1\}$. Then, $\sqrt{q}\le h\le1$ and $h\le R\mu$. We first consider the range $0<\mu\le\mu_{\mathrm{crit}}$, where the Boolean construction with $m\ge5$ applies.

\medskip\noindent
\underline{\emph{Case 1: $0<\mu\le\mu_{\mathrm{crit}}$}}.
Let $m$ be the largest positive odd integer satisfying $m\le c'/\mu$, and set
\begin{equation}
\label{eq:regimes-II-III-parameters}
    \lambda := 2h = 2 \min\{R\mu,1\},
    \quad\,\text{and}\quad\,
    p:=\left\lfloor\frac{c''}{\mu}\right\rfloor.
\end{equation}
Since $\mu\le\mu_{\mathrm{crit}}\le\min\{c'/6,c''/2\}$, we have
\begin{equation}
\label{eq:regimes-II-III-mp}
    \frac{2c'}{3\mu}\le m\le\frac{c'}{\mu},
    \quad\,\text{and}\quad\,
    \frac{c''}{2\mu}\le p\le\frac{c''}{\mu}.
\end{equation}
Moreover, $m\lambda\le 2c'R\le R/(4\sqrt{2})$, while $\lambda\le2$ and \crtCref{eq:choice-a-b} give
\[
    m\le\frac{c'}{\mu}\le\frac{\operatorname{sech}^2(2)}{2\mu}
    \le\frac{\operatorname{sech}^2(\lambda)}{2\mu}.
\]
Since $c''\le1/2$, we have $p\le1/(2\mu)$. Hence, the deterministic conditions of \crtCref{lem:generic-assouad-reduction} are satisfied.

We next bound $\mathcal{B}_{m,\lambda,q}$. First, note that for any $t > 0$, $\beta(t)$ satisfies the following:
\begin{align}
\label{eq:beta-quadratic}
    \beta(t)^2
    &= 
    \frac{1}{4} (t^2 + 2t\sqrt{t^2 + 4t} + t^2 + 4t)
    =
    \frac{2t}{4} \Bigl[t + \sqrt{t^2 + 4t} + 2\Bigr]
    =
    \frac{t}{2} \Bigl[2 \, \beta(t) + 2\Bigr]
    =
    t\{1+\beta(t)\}.
\end{align}

Write $t:=q/\sinh^2(2h)$ and $z:=1/\beta(t)$. \crtCref{eq:beta-quadratic} yields that
\[
    z(z+1)=\frac{1}{t}=\frac{\sinh^2(2h)}{q}.
\]
Since $h\ge\sqrt{q}$ and $\sinh(2h)>2h$, we have $z(z+1)>4$, and hence $z>4/3$. Furthermore,
\[
    \frac{1-q}{q}h^2\le\frac{h^2}{q}\le\frac{z(z+1)}{4}.
\]
For $z>4/3$, $1+z(z+1)/4\le z^2$, and therefore
\[
    \log(z)\ge\frac{1}{2}\log\Bigl(1+\frac{1-q}{q}h^2\Bigr).
\]
Since $\mathcal{B}_{m,\lambda,q}^{-1}=z^m$, \crtCref{eq:regimes-II-III-mp} yields
\begin{equation}
\label{eq:regimes-II-III-B-lower}
    \mathcal{B}_{m,\lambda,q}^{-1}
    \ge
    \exp\biggl\{
        \frac{c'}{3\mu}
        \log\biggl(
            1+\frac{1-q}{q}\min\{R^2\mu^2,1\}
        \biggr)
    \biggr\}.
\end{equation}

It remains to verify the sample-size requirement. Since $2\sqrt{q}\le\lambda\le2$, we have $G_\lambda\le C/q$. Moreover, $z(z+1)=\sinh^2(2h)/q\le C/q$, so $z\le C/\sqrt{q}$, and hence
\[
    \mathcal{B}_{m,\lambda,q}^{-1}\le\exp(CmL_q),
    \quad\,\text{and}\quad\,
    \bigl(G_\lambda\bigr)^m\le\exp(CmL_q).
\]
Using $m\le c'/\mu$, $p\le c''/\mu$, and $R\mu>\sqrt{q}$, it follows that
\begin{equation}
\label{eq:regimes-II-III-sample-control}
    \frac{1}{\mathcal{B}_{m,\lambda,q}}
    \max\left\{
        \frac{p}{q^2}, \frac{p}{q}\bigl(G_\lambda\bigr)^m, \frac{p^2}{qR^2}
    \right\}
    \le
    \frac{C}{\mu^2}
    \exp\left\{\frac{C'}{\mu}L_q\right\}.
\end{equation}
Thus, for sufficiently large universal constants $C_0,C_1>0$, the sample-size condition
\begin{equation*}
    n\ge\frac{C_0}{\mu^2}
    \exp\left\{\frac{C_1}{\mu}\log\left(\frac{e}{q}\right)\right\}
\end{equation*}
allows us to invoke \crtCref{lem:generic-assouad-reduction}. Combining that lemma with \crtCref{eq:regimes-II-III-mp,eq:regimes-II-III-B-lower} yields
\begin{equation*}
    \mathfrak{R}_n(R,\mu,q)
    \ge
    \frac{c_0}{nq\mu^2}
    \exp\biggl\{
        \frac{c_1}{\mu}
        \log\biggl(
            1+\frac{1-q}{q}\min\{R^2\mu^2,1\}
        \biggr)
    \biggr\},
\end{equation*}
for universal constants $c_0,c_1>0$.

\noindent
\underline{\emph{Case 2: $\mu_{\mathrm{crit}}<\mu\le\nicefrac{1}{3}$}}.

In this range, the choice $m\asymp\mu^{-1}$ may no longer yield $m\ge5$, so we instead use a two-point construction with $m=1$. 
Since $\mu\ge\mu_{\mathrm{crit}}$, the quantity $1/\mu$ is bounded by a universal constant, and a fixed-dimensional construction is sufficient. 

Write $h:=\min\{R\mu,1\}$, and choose
\[
    \lambda:=\frac{h}{8},
    \quad~\text{and}\quad~
    \alpha^2:=c'''\frac{\sinh^2(\lambda)}{nq^2}
\]
for a sufficiently small universal constant $c'''$. In this case, we may assume a less stringent sample-size condition
\begin{equation}
\label{eq:moderate-mu-sample-size}
    n\ge C q^{-3}
\end{equation}
for a sufficiently large universal constant $C > 0$. We show the same lower bound on the minimax risk as in \crtCref{eq:lower-bound-regimes-II-III} holds under the sample-size condition in \crtCref{eq:moderate-mu-sample-size}. For brevity, we defer the formal construction and statement (see \crtCref{lem:moderate-mu-lower-bound}) to \crtCref{proof:lem:moderate-mu-lower-bound}.

Also, note that there exist sufficiently large universal constants $C_0,C_1>0$ such that the sample-size condition as in \crtCref{eq:regimes-II-III-sample-size} implies the sample-size condition as in \crtCref{eq:moderate-mu-sample-size}, since for $\mu_{\mathrm{crit}}<\mu\le\nicefrac{1}{3}$, choosing $C_1\ge1$ yields
\[
    \exp\left\{\frac{C_1}{\mu}\log\left(\frac{e}{q}\right)\right\}
    \ge q^{-C_1/\mu}
    \ge q^{-3}.
\]

Combining the two cases, we have
\begin{equation}
\label{eq:lower-bound-regimes-II-III-unified}
    \mathfrak{R}_n(R,\mu,q)
    \ge
    \frac{c_0}{nq\mu^2}
    \exp\biggl\{
        \frac{c_1}{\mu}
        \log\Bigl(
            1+\frac{1-q}{q}\min\{R^2\mu^2,1\}
        \Bigr)
    \biggr\}
\end{equation}
whenever $R\mu>\sqrt{q}$, and the sample-size condition in \crtCref{eq:regimes-II-III-sample-size} holds. This proves \crtCref{claim:lower-bound-regimes-II-III}.
\end{proof}

We prove \crtCref{claim:lower-bound-regime-I} by separating the cases where $R/\sqrt{q}$ is bounded, and where $R/\sqrt{q}$ is unbounded. Set $u:=R/\sqrt{q}$, so that $u\le\mu^{-1}$ in the regime of the claim. Also, choose $U_0\ge\max\bigl\{6/c',2/c'',1\bigr\}$.

\medskip\noindent
\underline{\emph{Case 1: $u\le U_0$}}.
By \crtCref{prop:baseline-assouad} and the fact that $e^{R/4}\ge1$,
\[
    \mathfrak{R}_n(R,\mu,q)\ge c \cdot \min\left\{R^2,\frac{1}{nq\mu^2}\right\}.
\]
Hence, whenever $n\ge C/(q\mu^2R^2)$, we obtain $\mathfrak{R}_n(R,\mu,q)\ge c/(nq\mu^2)$. Since $u\le U_0$, we have
\begin{equation}
\label{eq:regime-I-small-u}
    \mathfrak{R}_n(R,\mu,q)\ge\frac{c}{nq\mu^2}\exp(cu)
    =\frac{c}{nq\mu^2}\exp\left\{c\frac{R}{\sqrt{q}}\right\}.
\end{equation}

\noindent
\underline{\emph{Case 2: $u > U_0$}}.
Set
\begin{equation}
\label{eq:regime-I-parameters}
    \lambda:=2\sqrt{q},
    \quad\,\text{and}\quad\,
    p:=\left\lfloor\frac{c''}{\mu}\right\rfloor.
\end{equation}

Also, let $m$ be the largest positive odd integer satisfying $m\le c'u$. Then, thanks to the choice of $U_0$, we have $m\ge5$, and since consecutive positive odd integers differ by $2$,
\begin{equation}
\label{eq:regime-I-m}
    \frac{2c'u}{3}\le m\le c'u.
\end{equation}
By \crtCref{eq:choice-a-b}, $m\lambda\le2c'R\le R/(4\sqrt{2})$. Moreover, since $u\le\mu^{-1}$ and $\lambda\le2$,
\[
    m\le\frac{c'}{\mu}\le\frac{\operatorname{sech}^2(2)}{2\mu}
    \le\frac{\operatorname{sech}^2(\lambda)}{2\mu}.
\]
Also, $u>U_0\ge2/c''$ and $u\le\mu^{-1}$ imply $c''/\mu>2$. Thus,
\begin{equation}
\label{eq:regime-I-p}
    \frac{c''}{2\mu}\le p\le\frac{c''}{\mu}.
\end{equation}
Since $c''\le1/2$, we also have $p\le (2\mu)^{-1}$. Therefore, the deterministic conditions \eqref{eq:generic-assouad-deterministic-conditions} in \crtCref{lem:generic-assouad-reduction} are satisfied.

We next control $\mathcal{B}_{m,\lambda,q}$ (\crtCref{eq:def-Bmlq}). For the present choice of $\lambda$, let $t := q/\sinh^2(2\sqrt{q})$.
Since $x\mapsto\sinh(x)/x$ is increasing on $(0,\infty)$, $1/\sinh^2(2)\le t\le1/4$. Recalling the function $\beta(\cdot)$ from \crtCref{eq:beta-function}, define
\[
    \underline{\beta}:=\beta\left(\frac{1}{\sinh^2(2)}\right)>0,
    \qquad
    \overline{\beta}:=\beta\left(\frac{1}{4}\right)=\frac{1+\sqrt{17}}{8}<1.
\]

Since $\beta(\cdot)$ is a strictly increasing function on $[0,\infty)$, we have $\underline{\beta}\le\beta(t)\le\overline{\beta}$. Hence, using \crtCref{eq:regime-I-m},
\begin{equation}
\label{eq:regime-I-B-bounds}
    \exp(\underline{c}u)\le\mathcal{B}_{m,\lambda,q}^{-1}\le\exp(\overline{c}u)
\end{equation}
for universal constants $\underline{c},\overline{c}>0$. 

It remains to verify the sample-size condition \eqref{eq:generic-assouad-sample-size} in \crtCref{lem:generic-assouad-reduction}. Since $\sinh(2\sqrt{q})\ge2\sqrt{q}$, we have $G_\lambda\le2+(4q)^{-1}\le C/q$, and therefore $(G_\lambda)^m \le \exp(CuL_q)$. Combining this with \crtCref{eq:regime-I-p,eq:regime-I-B-bounds}, and using $u\ge1$, $R^2=u^2q$, and $\mu\le1$, yields
\begin{equation}
\label{eq:regime-I-sample-size-control}
    \frac{1}{\mathcal{B}_{m,\lambda,q}}
    \max\left\{\frac{p}{q^2},\frac{p}{q}\,\bigl(G_\lambda\bigr)^m,\frac{p^2}{qR^2}\right\}
    \le\frac{C}{\mu^2}\exp(C'uL_q)
\end{equation}
for universal constants $C,C'>0$. Consequently, the sample-size condition \eqref{eq:generic-assouad-sample-size} of \crtCref{lem:generic-assouad-reduction} holds whenever
\begin{equation}
\label{eq:regime-I-large-u-sample-size}
    n\ge\frac{C}{\mu^2}
    \exp\left\{C'\frac{R}{\sqrt{q}}\log\left(\frac{e}{q}\right)\right\}.
\end{equation}

Applying \crtCref{lem:generic-assouad-reduction} and using \crtCref{eq:regime-I-p,eq:regime-I-B-bounds}, we conclude that
\begin{equation}
\label{eq:regime-I-large-u}
    \mathfrak{R}_n(R,\mu,q)
    \ge\frac{c}{nq\mu^2}
    \exp\left\{c\frac{R}{\sqrt{q}}\right\}.
\end{equation}

Combining \crtCref{eq:regime-I-small-u,eq:regime-I-large-u}, we obtain the desired lower bound throughout $R\mu\le\sqrt{q}$: provided
\[
    n\ge\frac{C_0}{q\mu^2R^2},
    \quad\,\text{and}\quad\,
    n\ge\frac{C_1}{\mu^2}
    \exp\left\{C_2\frac{R}{\sqrt{q}}\log\left(\frac{e}{q}\right)\right\},
\]
for sufficiently large universal constants $C_0,C_1,C_2>0$,
\begin{equation}
\label{eq:lower-bound-regime-I}
