\label{lem:majority-coefficients}
Let $r \in \mathbb{N} \cup \{0\}$ and suppose that $m = 2r + 1$.  The Fourier coefficients $\{g_U:U \subseteq [m]\}$ admit the representation
\[
g_U = 
\begin{cases}
~0\,, & \text{if~}\, |U|~ \text{is even};\\ 
~\displaystyle\frac{1}{2^{m-1}}
        \sum_{\substack{C\subseteq[m],\\ |C|\leq r}}
        (-1)^{|C\cap U|}\,, & \text{if~}\, |U|~ \text{is odd}.
\end{cases}
\]
Moreover, $\sum_{U \subseteq [m]} \, g_U^2 = 1$.

\label{lem:conditional-parseval}
$\mathcal{W}_{m,q}$, defined in \crtCref{eq:def-Wmq}, admits the representation:
\begin{equation*}
    \mathcal{W}_{m,q}
    ~=
    \sum_{\varnothing\neq U \subseteq [m]}
    \left\{
        \frac{q(1-\rho^2)}{\rho^2}
    \right\}^{|U|}
    h_U^2.
\end{equation*}

Consequently, $\mathcal{W}_{m,q}$ has the following explicit expression in terms of $q$, $\rho$, and $m$:
\begin{equation*}
    \mathcal{W}_{m,q}
    \,=\,
    4 \sum_{k=r+1}^m
    \binom{m}{k} \binom{k-1}{r}^{\!2}
    \left\{
        \frac{q(1-\rho^2)}{4\rho^2}
    \right\}^{\!k}.
\end{equation*}

Let us denote $\sigma_\rho:=\sqrt{1-\rho^2}$, and for all $U \subseteq [m] \setminus \varnothing$, define
\begin{equation}
\label{eq:psi-T}
    \psi_U(T)
    :=
    \prod_{j\in U} \underbrace{\frac{T_j-\rho}{\sigma_\rho}}_{=:\,\beta_{j}(\rho)},
    \qquad
    \psi_\varnothing\equiv1.
\end{equation}

Since $T_1,\ldots,T_m$ are independent, with $\mathbb{E}_0[T_j]=\rho$ and
$\operatorname{Var}_0(T_j)=1-\rho^2$, the collection $\{\psi_U:U \subseteq [m]\}$ is orthonormal under the null distribution of $T$. To see this, note the following.
\begin{itemize}
    \item For $A,B \subseteq [m]$ such that $A \neq B$, we have
    \begin{align*}
    \mathbb{E}\left[ \psi_A(T) \cdot \psi_B(T) \right]
    &=
    \mathbb{E}\left[ \prod_{j\in A \setminus B} \beta_{j}(\rho) \right] \cdot 
    \mathbb{E}\left[ \prod_{j\in B \setminus A} \beta_{j}(\rho) \right] \cdot 
    \mathbb{E}\left[ \prod_{j\in A \cap B} \beta_{j}(\rho)^2 \right] \\
    &= \prod_{j\in A \Delta B} \mathbb{E}\left[ \beta_{j}(\rho) \right] \cdot \prod_{j\in A \cap B} \mathbb{E}\left[ \beta_{j}(\rho)^2 \right] \\
    &= 0 \cdot \prod_{j\in A \cap B} \mathbb{E}\left[ \beta_{j}(\rho)^2 \right] \\
    &= 0.
    \end{align*}

    \item For $A = B$, we have
    \begin{align*}
    \mathbb{E}\left[ \psi_A(T)^2 \right]
    =
    \mathbb{E}\left[ \prod_{j\in A} \beta_{j}(\rho)^2 \right] 
    &= \prod_{j\in A} \mathbb{E}\left[ \beta_{j}(\rho)^2 \right] \\
    &= \prod_{j\in A} \frac{1}{1-\rho^2}\operatorname{var}\left[ T_{j} \right] \\
    &= \prod_{j\in A} \frac{1}{1-\rho^2} \left[ \frac{\exp(\lambda) + \exp(-\lambda)}{2 \cdot \cosh(\lambda)} - \rho^2 \right] 
    = \prod_{j\in A} \frac{1-\rho^2}{1-\rho^2} = 1.
    \end{align*}
\end{itemize}

Recall the definition of $\beta_j(\rho)$ in \crtCref{eq:psi-T}. For every $j\in[m]$, write
\[
    T_j
    =
    \rho + \sigma_\rho \frac{T_j-\rho}{\sigma_\rho}
    :=
    \rho + \sigma_\rho \, \beta_j(\rho).
\]
Thus, for every $W\subseteq[m]$, we have
\begin{align*}
    \chi_W(T) = \prod_{j \in W} (\rho + \sigma_\rho \beta_j(\rho)) 
    &= \prod_{j \in W} \left( \sum_{\mathcal{I}_j \in \{0, 1\}} \rho^{1 - \mathcal{I}_j} (\sigma_\rho \beta_j(\rho))^{\mathcal{I}_j} \right) \\ 
    &= \sum_{(\mathcal{I}_j)_{j \in W} \in \{0, 1\}^{|W|}} \prod_{j \in W} \rho^{1 - \mathcal{I}_j} (\sigma_\rho \beta_j(\rho))^{\mathcal{I}_j} \\ 
    &= \sum_{U \subseteq W} \left( \prod_{j \in W \setminus U} \rho \right) \left( \prod_{j \in U} \sigma_\rho \beta_j(\rho) \right) \quad \text{(letting } U = \{j \in W : \mathcal{I}_j = 1\}) \\ 
    &= \sum_{U \subseteq W} \rho^{|W| - |U|} \sigma_\rho^{|U|} \prod_{j \in U} \beta_j(\rho)\\ 
    &= \rho^{|W|} \sum_{U \subseteq W} \left(\frac{\sigma_\rho}{\rho}\right)^{|U|} \prod_{j \in U} \beta_j(\rho)
    ~=~ \rho^{|W|} \sum_{U \subseteq W} \left(\frac{\sigma_\rho}{\rho}\right)^{|U|} \psi_U(T)
\end{align*}

Using the definition of $J$ in \crtCref{eq:def-J}, and interchanging the two finite sums, we obtain
\begin{align*}
    J(T)
    =
    \sum_{W\subseteq[m]}
    g_W\rho^{-|W|}\chi_W(T)
    &= 
    \sum_{W\subseteq[m]}
    g_W\rho^{-|W|} 
    \rho^{|W|} \sum_{U \subseteq W} \left(\frac{\sigma_\rho}{\rho}\right)^{|U|} \psi_U(T)
    \\
    &=
    \sum_{U \subseteq [m]}
    \left(
        \frac{\sigma_\rho}{\rho}
    \right)^{|U|}
    \left(
        \sum_{W\supseteq U}g_W
    \right)
    \psi_U(T)\\ 
    &=
    \sum_{U \subseteq [m]}
    \left(
        \frac{\sigma_\rho}{\rho}
    \right)^{|U|}
    h_U \, \psi_U(T).
\end{align*}
For notational convenience, let us  define
\begin{equation}
    \label{eq:def-aU}
    a_U
    :=
    \left(
        \frac{\sigma_\rho}{\rho}
    \right)^{|U|}
    h_U,
    \qquad
    a_\varnothing = 1.
\end{equation}

Fix any deterministic set $\Bar{S}\subseteq[m]$. If $U\subseteq \Bar{S}$, then $\psi_U(T)$ is measurable with respect to $T_{\Bar{S}}$. If $U\nsubseteq \Bar{S}$, choose $j\in U\setminus \Bar{S}$. The factor $\beta_j(\rho) = (T_j-\rho)/\sigma_\rho$ is independent of $T_{\Bar{S}}$ and has mean zero. Hence,
\[
    \mathbb{E}_0[\psi_U(T)\mid T_{\Bar{S}}]
    \,=\,
    \begin{cases}
        \psi_U(T), & \text{if}\,~ U \subseteq \Bar{S},\\ 
        0, & \text{if}\,~ U\nsubseteq \Bar{S}.
    \end{cases}
\]
Therefore, since $a_{\varnothing} = 1$,
\[
    J_{\Bar{S}}(T_{\Bar{S}}) - 1
    =
    \sum_{\varnothing\neq U\subseteq \Bar{S}} a_U \, \psi_U(T).
\]
By orthonormality of the collection $\{\psi_U:U \subseteq [m]\}$, Parseval's theorem yields
\[
    \mathbb{E}_0
    \left[
        \left\{
            J_{\Bar{S}}(T_{\Bar{S}})-1
        \right\}^2
    \right]
    =
    \sum_{\varnothing\neq U\subseteq \Bar{S}} a_U^2
    =
    \sum_{\varnothing\neq U\subseteq [m]} a_U^2 \cdot \mathbf{1} \left\{U\subseteq \Bar{S}\right\}.
\]
Averaging over the independent random set $S$ yields
\begin{align*}
    \mathcal{W}_{m,q}
    =
    \sum_{\varnothing\neq U \subseteq [m]}
    a_U^2 \cdot \mathbb{P}(U\subseteq S)
    &=
    \sum_{\varnothing\neq U \subseteq [m]}
    q^{|U|}a_U^2 \\
    &=
    \sum_{\varnothing\neq U \subseteq [m]}
    q^{|U|}
    \left(
        \frac{\sigma_\rho}{\rho}
    \right)^{2|U|}
    h_U^2
    ~=
    \sum_{\varnothing\neq U \subseteq [m]}
    \left\{
        \frac{q(1-\rho^2)}{\rho^2}
    \right\}^{|U|}
    h_U^2,
\end{align*}
which proves the first claim.

Next, substituting the expression for $h_U$ from \crtCref{lem:exact-hU} in the preceding representation yields
\begin{align*}
    \mathcal{W}_{m,q}
    &=
    \sum_{\{U \subseteq [m] \,:\, |U| \geq r+1\}}
    \left\{
        \frac{q(1-\rho^2)}{\rho^2}
    \right\}^{|U|}
    h_U^2
    \\
    &=\sum_{k=r+1}^m
    \binom{m}{k} 
    \left\{
        \frac{q(1-\rho^2)}{\rho^2}
    \right\}^{\!k}
    \left[
        \frac{1}{2^{k-1}} \ (-1)^r \ \binom{k-1}{r}
    \right]^2
    \\
    &= 4 \sum_{k=r+1}^m
    \binom{m}{k} \binom{k-1}{r}^{\!2}
    \left\{
        \frac{q(1-\rho^2)}{4\rho^2}
    \right\}^{\!k},
\end{align*}
as in the second claim.

\label{lem:two-dimensional-patch}
Consider the two-point construction specialized to $m=1$, and let $\lambda,\alpha>0$. Suppose that
\begin{equation}
\label{eq:two-dimensional-patch-conditions}
    \alpha^2\le q,\qquad
    \alpha\le\frac{\tanh(\lambda)}{2},\qquad
    \frac{\sinh(2\alpha)}{\sinh(2\lambda)}\le1-2\mu,\qquad
    8(\lambda^2+\alpha^2)\le R^2.
\end{equation}
Then, for all $i\in\{0,1\}$, $P_i$ is a well-specified logistic model satisfying
\[
    \|X\|_2=1\quad\text{a.s.},\quad\;
    \mathbb{E}_i[XX^\top]\succeq\mu I_2,\quad\;
    \theta_i\in\Theta_R,\quad\;
    \text{and}\quad\;
    \|\theta_1-\theta_0\|_2^2 = 8\alpha^2.
\]
Moreover, for a universal constant $C>0$,
\[
    \chi^2(Q_1,Q_0)
    \le
    C\frac{q^2\alpha^2}{\sinh^2(\lambda)}.
\]
Consequently, there exist sufficiently small universal constants $\widetilde{c},c>0$ such that, if
$
    \alpha^2 = \widetilde{c}\, \frac{\sinh^2(\lambda)}{nq^2}
$
and the conditions in \crtCref{eq:two-dimensional-patch-conditions} hold, then
\begin{equation}
\label{eq:two-dimensional-patch-lower}
    \mathfrak{R}_n(R,\mu,q)
    \ge
    c\frac{\sinh^2(\lambda)}{nq^2}.
\end{equation}

\label{lem:moderate-mu-lower-bound}
Suppose that
\[
    \mu_{\mathrm{crit}}<\mu\le\mfrac{1}{3},
    \qquad
    R\mu>\sqrt{q}.
\]
If the sample-size condition $n \ge C q^{-3}$ holds for a sufficiently large universal constant $C>0$, then there exist universal constants $c_0,c_1>0$ for which
\begin{equation}
\label{eq:moderate-mu-unified-lower}
    \mathfrak{R}_n(R,\mu,q)
    \ge
    \frac{c_0}{nq\mu^2}
    \exp\left\{
        \frac{c_1}{\mu}
        \log\left(
            1+\frac{1-q}{q}\min\{R^2\mu^2,1\}
        \right)
    \right\}.
\end{equation}
